    t.socket('OUTPUT', 'Coordinates', 'NodeSocketVector', min_value=0.0, max_value=0.0)
    t.socket('INPUT', 'UV Map', 'NodeSocketVector', min_value=-10000.0, max_value=10000.0)
    t.socket('INPUT', 'Scale X', 'NodeSocketFloat', default_value=1.0, min_value=-10000.0, max_value=10000.0)
